package com.example.starter.slam.model;

/**
 * 位姿图边类型：里程计边或回环约束边。
 */
public enum EdgeType {
    /**
     * 相邻关键帧之间的里程计约束。
     */
    ODOMETRY,
    /**
     * 非相邻关键帧之间的回环闭合约束，需通过可信度阈值校验。
     */
    LOOP
}

package com.example.starter.slam.model;

/**
 * 边入库状态。回环约束校验不通过时仅保存为 REJECTED 审计记录，不进入有效图。
 */
public enum EdgeStatus {
    /**
     * 有效边：参与图版本递增与优化快照。
     */
    VALID,
    /**
     * 被拒绝的回环约束：仅作审计，不参与图构建，不触发图版本递增。
     */
    REJECTED
}

package com.example.starter.slam.model;

/**
 * 优化任务状态机：
 * PENDING（待执行，可能被合并）→ RUNNING（运行中）→
 * SUCCEEDED（成功）/ RETRYABLE_FAILED（可重试失败）/ SUPERSEDED（已被更新版本结果取代）。
 */
public enum TaskStatus {
    /**
     * 待执行；同一图上的多个 PENDING 请求会被合并为一个任务。
     */
    PENDING,
    /**
     * 优化器正在执行；运行中的任务不参与合并。
     */
    RUNNING,
    /**
     * 优化成功，结果已落库。
     */
    SUCCEEDED,
    /**
     * 可重试失败，已保存输入快照摘要、失败原因与重试次数；重试使用原快照。
     */
    RETRYABLE_FAILED,
    /**
     * 任务完成时已存在基于更多有效边的新版本结果，本任务结果被取代且不得覆盖新结果。
     */
    SUPERSEDED
}

