     */
    public List<OptimizationTask> findPendingForMerge() {
        return jdbc.query("""
                        SELECT * FROM opt_tasks
                        WHERE status = 'PENDING' AND merged_into_id IS NULL
                        ORDER BY id
                        """, ROW_MAPPER);
