        return jdbc.query("SELECT * FROM opt_tasks WHERE status = ? ORDER BY id",
                ROW_MAPPER, status.name());
    }

    private static String truncate(String reason) {
        if (reason == null) {
            return null;
        }
        return reason.length() <= 2000 ? reason : reason.substring(0, 2000);
    }
