package com.example.starter.slam.support;

import com.example.starter.slam.opt.EdgeConstraint;
import com.example.starter.slam.opt.NodePose;
import com.example.starter.slam.opt.OptimizationInput;
import com.example.starter.slam.opt.OptimizationOutput;
import com.example.starter.slam.opt.PoseGraphOptimizer;
import com.example.starter.slam.opt.RetryableOptimizationException;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * 测试用脚本化确定性优化器：
 * <ul>
 *   <li>按调用次数返回预设结果或抛出预设异常；</li>
 *   <li>可配置阻塞门闩，用于构造“运行中新版本到来”的真实并发场景；</li>
 *   <li>每次调用记录输入摘要，供断言重试使用的是原快照。</li>
 * </ul>
 */
public class ScriptedOptimizer implements PoseGraphOptimizer {

    private final Object lock = new Object();
    private final AtomicInteger calls = new AtomicInteger();
    private volatile RuntimeException failure;
    private volatile java.util.concurrent.CountDownLatch enteredGate;
    private volatile java.util.concurrent.CountDownLatch releaseGate;
    private final java.util.List<String> seenDigests =
            java.util.Collections.synchronizedList(new java.util.ArrayList<>());

    public void failOnceWith(String message) {
        this.failure = new RetryableOptimizationException(message);
    }

    /**
     * 下一次 optimize 调用进入后在 enteredGate 上计数，并阻塞直到 releaseGate 释放。
     */
    public void blockNextCall(java.util.concurrent.CountDownLatch enteredGate,
                              java.util.concurrent.CountDownLatch releaseGate) {
        this.enteredGate = enteredGate;
        this.releaseGate = releaseGate;
    }

    public int getCallCount() {
        return calls.get();
    }

    public java.util.List<String> getSeenDigests() {
        return java.util.List.copyOf(seenDigests);
    }

    @Override
    public OptimizationOutput optimize(OptimizationInput input) {
        calls.incrementAndGet();
        seenDigests.add(input.snapshotDigest());

        java.util.concurrent.CountDownLatch enter = enteredGate;
        java.util.concurrent.CountDownLatch release = releaseGate;
        if (enter != null) {
            enter.countDown();
        }
        if (release != null) {
            try {
                release.await(10, java.util.concurrent.TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RetryableOptimizationException("interrupted while gated", e);
            }
        }

        RuntimeException currentFailure = failure;
        if (currentFailure != null) {
            failure = null;
            throw currentFailure;
        }

        // 确定性输出：位姿保持快照先验值，代价 = 版本 + 边数（同输入必相同）
        Map<String, double[]> poses = new LinkedHashMap<>();
        for (NodePose node : input.keyframes()) {
            poses.put(node.keyframeId(), new double[]{node.x(), node.y(), node.theta()});
        }
        double cost = input.graphVersion() + input.edges().size() * 0.01;
        int edgeCount = (int) input.edges().stream().map(EdgeConstraint::edgeId).distinct().count();
        return new OptimizationOutput(poses, cost, edgeCount);
    }
}

